from __future__ import annotations
from math import gcd, hypot
from typing import Callable, List, Sequence, Tuple

Point = Tuple[float, float]

def euclidean(x: Point, y: Point) -> float:
    return hypot(x[0] - y[0], x[1] - y[1])

def path_length(f: Sequence[Point], n: int, dist: Callable[[Point, Point], float]) -> float:
    return sum(dist(f[i], f[i + 1]) for i in range(n))

def scale_reduction(K: float) -> Callable[[Point], Point]:
    return lambda p: (K * p[0], K * p[1])

def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def proper_divisors(n: int) -> List[int]:
    return [d for d in range(1, n) if n % d == 0]

def main() -> None:
    f: List[Point] = [(0.0, 0.0), (1.0, 2.0), (3.0, 1.0), (4.0, 4.0), (7.0, 3.0)]
    n = len(f) - 1
    print('pathLength =', path_length(f, n, euclidean))
    print('endpoint bound holds:', euclidean(f[0], f[n]) <= path_length(f, n, euclidean) + 1e-12)
    for k in range(n + 1):
        tail = sum(euclidean(f[i], f[i + 1]) for i in range(k, n))
        residual = path_length(f, n, euclidean) - (path_length(f, k, euclidean) + tail)
        print(f'concat residual at k={k}: {residual:.2e}')
    for K in (0.5, 1.0, 2.0, 3.5):
        phi = scale_reduction(K)
        reduced = [phi(p) for p in f]
        lhs = path_length(reduced, n, euclidean)
        rhs = K * path_length(f, n, euclidean)
        e2e = euclidean(phi(f[0]), phi(f[n]))
        print(f'K={K}: contraction {lhs <= rhs + 1e-9}, end-to-end {e2e <= rhs + 1e-9}')
    for (m, q) in [(12, 8), (15, 10), (21, 14), (100, 60)]:
        print(f'gcd(F{m},F{q})={gcd(fib(m), fib(q))} == F(gcd)={fib(gcd(m, q))}')
    for (N, p) in [(7, 13), (18, 19)]:
        assert N > 0 and fib(N) % p == 0
        assert not any(fib(d) % p == 0 for d in proper_divisors(N))
        witnesses = [k for k in range(1, N) if fib(k) % p == 0]
        print(f'bridge n={N}, p={p}: counterexamples {witnesses}')

if __name__ == '__main__':
    main()

from __future__ import annotations
from typing import Callable, List

def abs_dist(x: float, y: float) -> float:
    return abs(x - y)

def path_length_1d(f: List[float], n: int) -> float:
    return sum(abs_dist(f[i], f[i + 1]) for i in range(n))

def sharpness_witness(K: float, n: int) -> tuple[float, float]:
    f: List[float] = [float(i) for i in range(n + 1)]
    phi: Callable[[float], float] = lambda x: K * x
    reduced = [phi(x) for x in f]
    return path_length_1d(reduced, n), K * path_length_1d(f, n)

if __name__ == '__main__':
    for K in (0.0, 0.5, 1.0, 2.0, 10.0):
        lhs, rhs = sharpness_witness(K, 8)
        print(f'K={K}: pathLength(phi o f)={lhs}  K*pathLength(f)={rhs}  equal={abs(lhs - rhs) < 1e-12}')

