function PRIMITIVE_PART(n):
    r <- fib(n)
    for d in proper_divisors(n):
        g <- gcd(r, fib(d))
        while g > 1:
            r <- r / g
            g <- gcd(r, fib(d))
    return r

function PRIMITIVE_DIVISOR(n):
    r <- PRIMITIVE_PART(n)
    if r <= 1: return NONE       # n is exceptional (no primitive divisor)
    return SMALLEST_PRIME_FACTOR(r)

